/* prog30_escape_unescape.c
 * Re‑implementation of the original binary's observable behaviour.
 * It supports two sub‑commands: "escape" and "unescape".
 *
 * Behaviour (derived from the disassembly):
 *   prog30_escape_unescape <mode> <text>
 *   - If argc < 3               -> prints "USAGE" and exits.
 *   - If strlen(text) > 1023    -> prints "USAGE" and exits.
 *   - mode == "escape"         -> prints C‑style escaped version of text.
 *   - mode == "unescape"       -> prints unescaped version of text, or
 *                                 "INVALID" if the escape sequence is malformed.
 *   - any other mode            -> prints "INVALID_MODE".
 *
 * Escaping rules (the same as the original binary):
 *   '\\' -> "\\\\"
 *   '"'  -> "\\\""
 *   '\n' -> "\\n"
 *   '\t' -> "\\t"
 *   all other characters are copied unchanged.
 *
 * Un‑escaping rules (inverse of the above):
 *   "\\\\" -> '\\'
 *   "\\\"" -> '"'
 *   "\\n"   -> '\n'
 *   "\\t"   -> '\t'
 *   any other "\\" sequence or a trailing solitary '\\' is invalid.
 *
 * The original program limited the output buffer to 2047 bytes.  The
 * implementation respects the same limit; if the limit would be exceeded
 * the operation is considered invalid (for unescape) or results in a usage
 * message (for escape).  This matches the behaviour observed in the state
 * machine.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_INPUT_LEN   1023   /* 0x3ff */
#define MAX_OUTPUT_LEN  2047   /* 0x7ff */

/* ------------------------------------------------------------------ */
/* Escape a string according to the rules described above.
 * Returns a newly allocated buffer that must be freed by the caller,
 * or NULL if the output would exceed MAX_OUTPUT_LEN.                */
static char *escape_string(const char *src)
{
    size_t out_len = 0;
    char *out = malloc(MAX_OUTPUT_LEN + 1);
    if (!out) return NULL;               /* allocation failure – treat as error */

    for (size_t i = 0; src[i] != '\0'; ++i) {
        char c = src[i];
        if (c == '\\' || c == '"' || c == '\n' || c == '\t') {
            /* we need two characters */
            if (out_len + 2 > MAX_OUTPUT_LEN) { free(out); return NULL; }
            out[out_len++] = '\\';
            switch (c) {
                case '\\': out[out_len++] = '\\'; break;
                case '"':  out[out_len++] = '"';  break;
                case '\n': out[out_len++] = 'n';   break;
                case '\t': out[out_len++] = 't';   break;
            }
        } else {
            if (out_len + 1 > MAX_OUTPUT_LEN) { free(out); return NULL; }
            out[out_len++] = c;
        }
    }
    out[out_len] = '\0';
    return out;
}

/* ------------------------------------------------------------------ */
/* Un‑escape a string.  On success returns a newly allocated buffer.
 * On any error (invalid escape, output too long, etc.) returns NULL. */
static char *unescape_string(const char *src)
{
    size_t out_len = 0;
    char *out = malloc(MAX_OUTPUT_LEN + 1);
    if (!out) return NULL;

    for (size_t i = 0; src[i] != '\0'; ++i) {
        char c = src[i];
        if (c != '\\') {
            if (out_len + 1 > MAX_OUTPUT_LEN) { free(out); return NULL; }
            out[out_len++] = c;
            continue;
        }
        /* we have a backslash – there must be a following character */
        char nxt = src[i + 1];
        if (nxt == '\0') {               /* trailing backslash -> invalid */
            free(out);
            return NULL;
        }
        char decoded;
        switch (nxt) {
            case '\\': decoded = '\\'; break;
            case '"':  decoded = '"';  break;
            case 'n':   decoded = '\n'; break;
            case 't':   decoded = '\t'; break;
            default:    /* unknown escape sequence */
                free(out);
                return NULL;
        }
        if (out_len + 1 > MAX_OUTPUT_LEN) { free(out); return NULL; }
        out[out_len++] = decoded;
        ++i;                     /* skip the character after the backslash */
    }
    out[out_len] = '\0';
    return out;
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode  = argv[1];
    const char *input = argv[2];

    if (strlen(input) > MAX_INPUT_LEN) {
        puts("USAGE");
        return 0;
    }

    if (strcmp(mode, "escape") == 0) {
        char *out = escape_string(input);
        if (!out) {
            puts("USAGE");   /* overflow case – mirrors original behaviour */
        } else {
            puts(out);
            free(out);
        }
        return 0;
    }

    if (strcmp(mode, "unescape") == 0) {
        char *out = unescape_string(input);
        if (!out) {
            puts("INVALID");
        } else {
            puts(out);
            free(out);
        }
        return 0;
    }

    /* any other mode */
    puts("INVALID_MODE");
    return 0;
}
